-- Generated by scripts/build-ai-checked-construction-catalog.ts.
-- Install the mandatory guard and matching runtimes before catalog activation.
-- New immutable versions preserve older manifests, tool handlers and settings.
begin;
do $checked_construction_catalog$
declare contracts jsonb:=$checked_construction_contracts$[
  {
    "key": "tools.design_project_cad",
    "description": "Render a requested drawing of one exact saved, checked construction revision. Every project drawing needs its own construction source with stable part IDs, dimensions, placements, pinned catalog materials and declared joints before CAD. Read or save the construction, compare it with the owner requirements and original reference images, run check_construction_draft and correct that same construction before calling this tool. For an older drawing, use transition_legacy_drawing to retain its geometry and identities and establish the missing material/joint evidence. Pass the saved construction Artifact ID, or its already linked drawing ID, and the exact receipt revision. CAD reuses the saved geometry; it cannot design a replacement assembly. Reference pixels and the original requirements accompany independent candidate review. Reuse the same request_id on retry. Returns a checked candidate that still needs save_cad_design.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "request_id": {
          "type": [
            "string",
            "null"
          ],
          "description": "Use the saved request ID only when the current owner message requests or continues a drawing deliverable. A message about the same object, a correction, an image description, or a project-text update does not by itself request CAD. Complete a text-only request through its own read/write tools and finish the reply without resuming the drawing. When a drawing is requested, reuse this ID, its saved requirements and a source-current draft; no extra confirmation is needed. Null only for a new drawing request. With an ID, pass handoff:null and requirement_changes:[] to preserve ALL requirements; put explicit requirement corrections in requirement_changes."
        },
        "brief": {
          "type": "string"
        },
        "handoff": {
          "anyOf": [
            {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "deliverable": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 2000
                },
                "requirements": {
                  "type": "array",
                  "minItems": 1,
                  "maxItems": 24,
                  "items": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "requirement": {
                        "type": "string",
                        "minLength": 1,
                        "maxLength": 2000
                      },
                      "basis": {
                        "type": "string",
                        "enum": [
                          "user_request",
                          "project_record",
                          "working_assumption"
                        ]
                      },
                      "source_ref": {
                        "type": [
                          "string",
                          "null"
                        ],
                        "maxLength": 500
                      }
                    },
                    "required": [
                      "requirement",
                      "basis",
                      "source_ref"
                    ]
                  }
                },
                "coordinates": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "origin": {
                      "type": [
                        "string",
                        "null"
                      ],
                      "maxLength": 500
                    },
                    "positive_x": {
                      "type": [
                        "string",
                        "null"
                      ],
                      "maxLength": 500
                    },
                    "positive_y": {
                      "type": [
                        "string",
                        "null"
                      ],
                      "maxLength": 500
                    },
                    "positive_z": {
                      "type": [
                        "string",
                        "null"
                      ],
                      "maxLength": 500
                    }
                  },
                  "required": [
                    "origin",
                    "positive_x",
                    "positive_y",
                    "positive_z"
                  ]
                },
                "views": {
                  "type": "array",
                  "minItems": 1,
                  "maxItems": 4,
                  "uniqueItems": true,
                  "items": {
                    "type": "string",
                    "enum": [
                      "front",
                      "right",
                      "top",
                      "isometric"
                    ]
                  }
                },
                "unresolved": {
                  "type": "array",
                  "maxItems": 20,
                  "items": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 2000
                  }
                }
              },
              "required": [
                "deliverable",
                "requirements",
                "coordinates",
                "views",
                "unresolved"
              ]
            },
            {
              "type": "null"
            }
          ],
          "description": "New request only: transfer owner requirements without IDs; the server creates and persists their identities. Map coordinates and views, keep unknown directions null and cite exact source refs. Resume with null: the server reads the saved handoff, including earlier corrections. Use requirement_changes only for explicit additions or changes."
        },
        "requirement_changes": {
          "type": "array",
          "maxItems": 24,
          "description": "Explicit changes to a saved request only. Empty to resume. Copy requirement_id from the saved handoff to update it; null only for a genuinely new requirement. Never invent an ID. Earlier requirements are retained.",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "requirement_id": {
                "type": [
                  "string",
                  "null"
                ],
                "maxLength": 40
              },
              "requirement": {
                "type": "string",
                "minLength": 1,
                "maxLength": 2000
              },
              "basis": {
                "type": "string",
                "enum": [
                  "user_request",
                  "project_record",
                  "working_assumption"
                ]
              },
              "source_ref": {
                "type": [
                  "string",
                  "null"
                ],
                "maxLength": 500
              }
            },
            "required": [
              "requirement_id",
              "requirement",
              "basis",
              "source_ref"
            ]
          }
        },
        "area_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "component_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "step_id": {
          "type": [
            "string",
            "null"
          ],
          "description": "Current work Step this drawing supports; read the plan and pass its exact ID when relevant. Null for a project-wide drawing. Planning is a phase."
        },
        "artifact_id": {
          "type": "string",
          "description": "Exact saved construction Artifact ID, or a drawing already linked to that construction. A missing construction must be saved and checked first. The server renders its geometry verbatim into a linked drawing."
        },
        "construction_revision": {
          "type": "integer",
          "minimum": 1,
          "maximum": 999999999,
          "description": "Copy the exact saved/read construction revision. Required for every project drawing. The server checks this version and preserves it on resume; it cannot substitute a newer design."
        }
      },
      "required": [
        "request_id",
        "brief",
        "handoff",
        "requirement_changes",
        "area_id",
        "component_id",
        "step_id",
        "artifact_id",
        "construction_revision"
      ]
    }
  },
  {
    "key": "tools.save_cad_design",
    "description": "Save the exact independently reviewed rendering of its saved, checked construction revision from this turn, including the construction source pin and plan Step link. Source, material and target revisions are checked again at publication. This concept drawing is not measured truth or structural certification.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "request_quote": {
          "type": "string"
        }
      },
      "required": [
        "request_quote"
      ]
    }
  },
  {
    "key": "tools.plan_cad_pieces",
    "description": "Queue drawings for 2-12 exact saved construction revisions of a larger build. Save and check every piece first, with stable part IDs, pinned materials, declared joints and placements in the shared assembly coordinates. Pass each construction Artifact ID and its exact receipt revision. All pieces are checked before any request is stored or released. Workers render the pinned geometry one piece at a time without designing replacement assemblies. Give each piece its requirements, shared origin/axes and requested views. A failed piece retains its request_id for retry. For one construction use design_project_cad.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "assembly_title",
        "assembly_brief",
        "area_id",
        "pieces"
      ],
      "properties": {
        "assembly_title": {
          "type": "string",
          "maxLength": 200
        },
        "assembly_brief": {
          "type": "string",
          "maxLength": 3000,
          "description": "Whole-build intent, shared origin/axes and how the pieces meet."
        },
        "area_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "pieces": {
          "type": "array",
          "minItems": 2,
          "maxItems": 12,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "piece_key",
              "brief",
              "component_id",
              "handoff",
              "artifact_id",
              "construction_revision"
            ],
            "properties": {
              "piece_key": {
                "type": "string",
                "pattern": "^[a-z][a-z0-9_-]{0,39}$",
                "description": "Stable short key, e.g. wall_north, floor, roof, bunk_bed."
              },
              "brief": {
                "type": "string",
                "maxLength": 5000
              },
              "component_id": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "handoff": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "deliverable": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 2000
                  },
                  "requirements": {
                    "type": "array",
                    "minItems": 1,
                    "maxItems": 24,
                    "items": {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "requirement": {
                          "type": "string",
                          "minLength": 1,
                          "maxLength": 2000
                        },
                        "basis": {
                          "type": "string",
                          "enum": [
                            "user_request",
                            "project_record",
                            "working_assumption"
                          ]
                        },
                        "source_ref": {
                          "type": [
                            "string",
                            "null"
                          ],
                          "maxLength": 500
                        }
                      },
                      "required": [
                        "requirement",
                        "basis",
                        "source_ref"
                      ]
                    }
                  },
                  "coordinates": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "origin": {
                        "type": [
                          "string",
                          "null"
                        ],
                        "maxLength": 500
                      },
                      "positive_x": {
                        "type": [
                          "string",
                          "null"
                        ],
                        "maxLength": 500
                      },
                      "positive_y": {
                        "type": [
                          "string",
                          "null"
                        ],
                        "maxLength": 500
                      },
                      "positive_z": {
                        "type": [
                          "string",
                          "null"
                        ],
                        "maxLength": 500
                      }
                    },
                    "required": [
                      "origin",
                      "positive_x",
                      "positive_y",
                      "positive_z"
                    ]
                  },
                  "views": {
                    "type": "array",
                    "minItems": 1,
                    "maxItems": 4,
                    "uniqueItems": true,
                    "items": {
                      "type": "string",
                      "enum": [
                        "front",
                        "right",
                        "top",
                        "isometric"
                      ]
                    }
                  },
                  "unresolved": {
                    "type": "array",
                    "maxItems": 20,
                    "items": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 2000
                    }
                  }
                },
                "required": [
                  "deliverable",
                  "requirements",
                  "coordinates",
                  "views",
                  "unresolved"
                ]
              },
              "artifact_id": {
                "type": "string",
                "description": "Exact saved construction Artifact ID for this piece."
              },
              "construction_revision": {
                "type": "integer",
                "minimum": 1,
                "maximum": 999999999,
                "description": "Exact saved/read construction revision; every piece requires a source."
              }
            }
          }
        }
      }
    }
  }
]$checked_construction_contracts$::jsonb;
 append jsonb:=$checked_construction_append$[
  {
    "key": "tools.design_project_cad",
    "content": "Every project CAD drawing requires a saved construction and its exact revision. This policy supersedes older free-design intake guidance. Prepare the parts, dimensions, placements, pinned catalog materials and declared joints through the construction tools; compare with the current owner requirements and selected reference images, check and correct that same construction, then render it verbatim. Existing legacy drawings use transition_legacy_drawing; never invent missing material or joint evidence. A failed check returns to construction correction; CAD cannot replace or repair the construction. Text-only work still finishes through its own writer without CAD."
  },
  {
    "key": "tools.save_construction_draft",
    "content": "This shared construction is the required source for every project drawing. Preserve stable part IDs, explicit dimensions and placements, exact catalog material revisions and declared joint endpoints/methods. Compare the saved geometry with the owner requirements, reference image and stated coordinates before requesting CAD. Run check_construction_draft on the receipt revision and correct the same construction if needed. A single physical part may legitimately need no joint; do not invent one. Unknown material/joint evidence stays unknown and may prevent a drawing."
  },
  {
    "key": "tools.check_construction_draft",
    "content": "Mandatory before project CAD. Check the exact saved construction revision; correct its reported issues through the construction writer, then check the new receipt revision. The drawing stage rechecks current sources and renders that version without geometry-design calls. Concept readiness does not certify strength, fastener capacity or fabrication readiness."
  },
  {
    "key": "bob.frame.outstanding",
    "content": "For a requested drawing continuation, its exact saved construction must pass the construction check before any CAD work. If a legacy request has no construction source, read its existing geometry and prepare the explicit legacy transition with material/joint evidence first. Reuse the original requirements and part identities. A text-only request still leaves the drawing parked."
  }
]$checked_construction_append$::jsonb;
 feedback jsonb:=$checked_construction_feedback${
  "key": "feedback.cad-assistant.next-action.facd61c3e829",
  "content": "Read the saved construction or prepare it through save_construction_draft; an older drawing uses transition_legacy_drawing to preserve its geometry and IDs. Establish explicit material and joint evidence, check_construction_draft and correct that SAME construction until its exact revision is ready. Then request the drawing with that source ID/revision. Do not ask the CAD stage to invent or repair a construction. Unknowns remain explicit."
}$checked_construction_feedback$::jsonb;
 patch jsonb; prior shared.ai_prompt_versions; definition jsonb; content text; next_version integer; version_uuid uuid; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 for patch in select jsonb_build_object('key',key) from (
  select value->>'key' key from jsonb_array_elements(contracts)
  union select value->>'key' from jsonb_array_elements(append)
  union select feedback->>'key'
 ) keys loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id
   where p.app='bob' and p.prompt_key=patch->>'key' for update of p;
  if not found then raise exception 'checked_construction_contract_missing'; end if;
  definition:=prior.definition;content:=prior.content;
  for patch in select value from jsonb_array_elements(contracts) where value->>'key'=(select prompt_key from shared.ai_prompts where id=prior.prompt_id) loop
   if prior.definition_kind<>'tool_contract' then raise exception 'checked_construction_contract_kind'; end if;
   definition:=definition||jsonb_build_object('description',patch->>'description','parameters',patch->'parameters','required_parameters',patch#>'{parameters,required}','optional_parameters','[]'::jsonb);
  end loop;
  for patch in select value from jsonb_array_elements(append) where value->>'key'=(select prompt_key from shared.ai_prompts where id=prior.prompt_id) loop
   if prior.definition_kind='instruction_fragment' then content:=content||E'\n\n'||(patch->>'content');
   elsif prior.definition_kind='tool_contract' then definition:=jsonb_set(definition,'{additional_description}',to_jsonb(coalesce(definition->>'additional_description','')||E'\n\n'||(patch->>'content')));
   else raise exception 'checked_construction_append_kind'; end if;
  end loop;
  if (select prompt_key from shared.ai_prompts where id=prior.prompt_id)=feedback->>'key' then content:=feedback->>'content'; end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','checked-construction-required'),content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object((select prompt_key from shared.ai_prompts where id=prior.prompt_id),version_uuid);
 end loop;
 perform shared.activate_ai_catalog('bob',activation);
end $checked_construction_catalog$;
commit;
